CREATE SCHEMA IF NOT EXISTS oc_semantic_index;
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_collections(collection_id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,policy_version TEXT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_semantic_index.embedding_models(model_id BIGSERIAL PRIMARY KEY,provider_type TEXT NOT NULL,provider_name TEXT NOT NULL,model_name TEXT NOT NULL,model_version TEXT NOT NULL,vector_dimension INTEGER NOT NULL CHECK(vector_dimension>0),distance_metric TEXT NOT NULL,maximum_input_size INTEGER,tokenizer TEXT,normalization JSONB NOT NULL DEFAULT '{}',configuration_hash CHAR(64) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,local_execution BOOLEAN NOT NULL,data_handling_classification TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),retired_at TIMESTAMPTZ,UNIQUE(provider_name,model_name,model_version,configuration_hash));
CREATE TABLE IF NOT EXISTS oc_semantic_index.embedding_configurations(configuration_id BIGSERIAL PRIMARY KEY,model_id BIGINT NOT NULL REFERENCES oc_semantic_index.embedding_models(model_id),configuration JSONB NOT NULL,configuration_hash CHAR(64) NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_runs(index_run_id BIGSERIAL PRIMARY KEY,model_id BIGINT NOT NULL REFERENCES oc_semantic_index.embedding_models(model_id),configuration_id BIGINT NOT NULL REFERENCES oc_semantic_index.embedding_configurations(configuration_id),state TEXT NOT NULL CHECK(state IN('PENDING','PLANNING','PLANNED','INDEXING','PAUSING','PAUSED','CANCELLING','CANCELLED','PARTIAL','COMPLETED','FAILED')),pipeline_version TEXT NOT NULL,collection_policy_version TEXT NOT NULL,cancellation_requested_at TIMESTAMPTZ,metrics JSONB NOT NULL DEFAULT '{}',started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),completed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_run_items(item_id BIGSERIAL PRIMARY KEY,index_run_id BIGINT NOT NULL REFERENCES oc_semantic_index.index_runs(index_run_id),source_object_type TEXT NOT NULL,source_object_id BIGINT NOT NULL,revision_id BIGINT NOT NULL REFERENCES oc_import.document_revisions(revision_id),extraction_run_id BIGINT NOT NULL REFERENCES oc_document_intelligence.extraction_runs(extraction_run_id),eligibility TEXT NOT NULL,plan_action TEXT NOT NULL,state TEXT NOT NULL,failure JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(index_run_id,source_object_type,source_object_id));
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_documents(index_document_id BIGSERIAL PRIMARY KEY,source_object_type TEXT NOT NULL,source_object_id BIGINT NOT NULL,revision_id BIGINT NOT NULL REFERENCES oc_import.document_revisions(revision_id),extraction_run_id BIGINT NOT NULL REFERENCES oc_document_intelligence.extraction_runs(extraction_run_id),parent_object_type TEXT,parent_object_id BIGINT,representation_type TEXT NOT NULL,language TEXT NOT NULL,content_hash CHAR(64) NOT NULL,metadata_hash CHAR(64) NOT NULL,model_id BIGINT NOT NULL REFERENCES oc_semantic_index.embedding_models(model_id),configuration_id BIGINT NOT NULL REFERENCES oc_semantic_index.embedding_configurations(configuration_id),pipeline_version TEXT NOT NULL,collection_policy_version TEXT NOT NULL,eligibility TEXT NOT NULL,exclusion_reason TEXT,metadata JSONB NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE,version INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(source_object_type,source_object_id,revision_id,extraction_run_id,content_hash,metadata_hash,model_id,configuration_id,pipeline_version,collection_policy_version));
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_document_collections(index_document_id BIGINT REFERENCES oc_semantic_index.index_documents(index_document_id),collection_id BIGINT REFERENCES oc_semantic_index.index_collections(collection_id),PRIMARY KEY(index_document_id,collection_id));
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_vectors(vector_id BIGSERIAL PRIMARY KEY,index_document_id BIGINT NOT NULL REFERENCES oc_semantic_index.index_documents(index_document_id),index_run_id BIGINT NOT NULL REFERENCES oc_semantic_index.index_runs(index_run_id),model_id BIGINT NOT NULL REFERENCES oc_semantic_index.embedding_models(model_id),vector_dimension INTEGER NOT NULL,vector_payload JSONB NOT NULL,content_hash CHAR(64) NOT NULL,quality_flags JSONB NOT NULL DEFAULT '[]',active BOOLEAN NOT NULL DEFAULT TRUE,version INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(index_document_id,model_id,version));
CREATE TABLE IF NOT EXISTS oc_semantic_index.lexical_index_records(lexical_id BIGSERIAL PRIMARY KEY,index_document_id BIGINT NOT NULL UNIQUE REFERENCES oc_semantic_index.index_documents(index_document_id),normalized_text TEXT NOT NULL,search_vector TSVECTOR,language TEXT NOT NULL,title TEXT,headings JSONB NOT NULL DEFAULT '[]',authors JSONB NOT NULL DEFAULT '[]',identifiers JSONB NOT NULL DEFAULT '{}',metadata JSONB NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS semantic_lexical_gin ON oc_semantic_index.lexical_index_records USING GIN(search_vector);
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_source_anchors(index_document_id BIGINT REFERENCES oc_semantic_index.index_documents(index_document_id),anchor_id BIGINT REFERENCES oc_document_intelligence.source_anchors(anchor_id),ordered_span INTEGER NOT NULL,PRIMARY KEY(index_document_id,ordered_span));
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_warnings(warning_id BIGSERIAL PRIMARY KEY,index_run_id BIGINT NOT NULL REFERENCES oc_semantic_index.index_runs(index_run_id),item_id BIGINT REFERENCES oc_semantic_index.index_run_items(item_id),code TEXT NOT NULL,message TEXT,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_review_items(review_id BIGSERIAL PRIMARY KEY,index_run_id BIGINT REFERENCES oc_semantic_index.index_runs(index_run_id),item_id BIGINT REFERENCES oc_semantic_index.index_run_items(item_id),reason TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'OPEN',decision TEXT,rationale TEXT,actor TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_tombstones(tombstone_id BIGSERIAL PRIMARY KEY,source_object_type TEXT NOT NULL,source_object_id BIGINT NOT NULL,prior_index_document_id BIGINT REFERENCES oc_semantic_index.index_documents(index_document_id),reason TEXT NOT NULL,effective_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),replacement_index_document_id BIGINT REFERENCES oc_semantic_index.index_documents(index_document_id),actor TEXT NOT NULL,audit_metadata JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_run_events(event_id BIGSERIAL PRIMARY KEY,index_run_id BIGINT NOT NULL REFERENCES oc_semantic_index.index_runs(index_run_id),event_type TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS oc_semantic_index.index_quality_metrics(metric_id BIGSERIAL PRIMARY KEY,index_run_id BIGINT NOT NULL REFERENCES oc_semantic_index.index_runs(index_run_id),metric_name TEXT NOT NULL,metric_value NUMERIC,dimensions JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
